mapper.select:
SELECT O.ORDER_ID, O.ORDER_TYPE, O.ORDER_STATUS, O.TOTAL_PRICE, O.DISCOUNT_AMT, O.CREATED_AT, O.USER_ID,
U.USER_NAME AS RECEIVER_NAME, U.USER_PHONE AS RECEIVER_PHONE, A.ZIPCODE, A.ADDRESS AS DELIVERY_ADDR, A.DETAILED_ADDRESS AS DELIVERY_DETAIL_ADDR,
P.PRODUCT_NAME, OI.UNIT_PRICE AS ITEM_PRICE, OI.QUANTITY AS ITEM_COUNT, O.ORDER_TYPE AS ITEM_TYPE, OI.START_DATE, OI.END_DATE FROM ORDERS O INNER JOIN ORDER_ITEM OI ON O.ORDER_ID = OI.ORDER_ID INNER JOIN PRODUCT P ON OI.PRODUCT_ID = P.PRODUCT_ID INNER JOIN USER U ON O.USER_ID = U.USER_ID LEFT JOIN USER_ADDRESS A ON O.USER_ID = A.USER_ID AND A.DEFAULT_YN = 'Y' WHERE O.ORDER_ID = #{orderId}
AND O.USER_ID = #{userId}
